<?php

declare(strict_types=1);

require_once __DIR__ . '/Fixtures/IsolatedFinDatabase.php';
require_once __DIR__ . '/DatabaseTestCase.php';
require_once __DIR__ . '/Fixtures/SyntheticStatementGenerator.php';
require_once __DIR__ . '/Fixtures/FinAccountBuilder.php';

use PHPUnit\Framework\TestCase;
use Tests\Php\Fixtures\FinAccountBuilder;
use Tests\Php\Fixtures\IsolatedFinDatabase;
use Tests\Php\Fixtures\SyntheticStatementGenerator;

/**
 * Proves that the self-owned synthetic fixtures are accepted by the real
 * parser/import path. Every fixture is generated by the test itself and
 * contains only invented values.
 */
final class SyntheticStatementParserContractTest extends TestCase
{
    private IsolatedFinDatabase $db;
    private string $tmpDir;
    private FinAccountBuilder $builder;

    protected function setUp(): void
    {
        $this->db = IsolatedFinDatabase::create();
        DatabaseTestCase::seedNeutralImportProfiles($this->db->db());
        $this->tmpDir = sys_get_temp_dir() . '/fin-synthetic-' . bin2hex(random_bytes(4));
        if (!mkdir($this->tmpDir, 0700, true) && !is_dir($this->tmpDir)) {
            throw new RuntimeException('Could not create temp dir');
        }
        $this->builder = FinAccountBuilder::for($this->db->db());
    }

    protected function tearDown(): void
    {
        if (is_dir($this->tmpDir)) {
            foreach (glob($this->tmpDir . '/*') ?: [] as $f) {
                @unlink($f);
            }
            @rmdir($this->tmpDir);
        }
        $this->db->destroy();
    }





    public function testMalformedSyntheticRowKeepsProblemEvidenceAndCreatesNoFinancialRecord(): void
    {
        $accountId = $this->builder->account(
            'Test Bank Account',
            'TEST-SB-MAL-' . bin2hex(random_bytes(3)),
            'CURRENCY',
            0.0,
            '2026-01-01'
        );
        $rows = [
            $this->builder->row('2026-05-01', -42.5, 'Valid Test Bank row', 957.5),
            $this->builder->row('not-a-date', -10.0, 'Malformed date row', 947.5),
        ];
        $path = $this->builder->writeStatement(
            SyntheticStatementGenerator::FORMAT_SIGNED,
            $this->tmpDir,
            'signed-malformed',
            $rows,
            ['account_number' => 'TEST-SB-MAL-' . bin2hex(random_bytes(3)), 'account_name' => 'Privatkonto synthetic']
        );
        $result = import_statement_evidence($this->db->db(), $accountId, basename($path), (string)file_get_contents($path));
        self::assertTrue($result['ok']);
        $parseProblemCount = (int)$result['preview']['parse_problem_count'];
        self::assertGreaterThanOrEqual(1, $parseProblemCount);
        self::assertSame(0, (int)$this->db->db()->query('SELECT COUNT(*) FROM transactions')->fetchColumn());
        self::assertSame(0, (int)$this->db->db()->query('SELECT COUNT(*) FROM account_events')->fetchColumn());
    }
}
